head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.strSch = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function(e) {
    try {
        // 초기화 함수
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context: "ULDSTF92007.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    await scwin.selectList();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Search_onclick
 * @description img_Search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_Search_onclick = async function (e) {
    try {
        // 조회 버튼 클릭
        await scwin.selectList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92007.img_Search_onclick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description img_Close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_Close_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92007.img_Close_onclick" });
    }
};

/**
 * @method
 * @name grd_IsuInst_oncelldblclick
 * @description grd_IsuInst 셀 더블클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_IsuInst_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.setParam(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92007.grd_IsuInst_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name selectList
 * @description 기업목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.selectList = async function() {

    const param = $c.data.getParameter() ?? {};

    const parMkt = param.mktIdx ?? "";
    const parRsn = param.rsnIdx ?? "";
    const parAgn = param.agnIdx ?? "";
    // 기업인수목적회사 구분 (2010.05.30 추가)
    const parSpa = param.agnIdx ?? "N";
    let parGubn = $c.util.isEmpty(param.stkcertKindCd) ? "06" : param.stkcertKindCd.substring(8,11); // TODO: default 확인필요 "" -> "06"

    if( parGubn === "" ||parGubn === "000" || parGubn === "KDR" ) {
        parGubn = "1";
    }else{
        parGubn = "2";
    }
    // 유가 관리종목지정, 유가 매매거래정지는 대분류로사유찾기(ULDSTF92008)를 이용
    if ((parRsn === "") || ((parMkt === '1') && (parRsn === '05')) || ((parMkt === '1') && (parRsn === '07'))) {
        await $c.win.alert("사유코드가 지정되지 않았거나 대분류가 필요한 사유입니다.");
        $c.win.closePopup();
    }
    scwin.strSch = param.codIdx ?? "";

    // 데이터셋 초기화
    scwin.initDs();
    let sbmOptions = {};

    dma_searchReq.set("mkt", parMkt);
    dma_searchReq.set("rsn", parRsn);
    dma_searchReq.set("agn", parAgn);
    dma_searchReq.set("gubn", parGubn);
    dma_searchReq.set("spac", parSpa);
    sbmOptions = {
            id: "sbm_selectList",
            action: "/api/listing/common/pop/etc/rsncd/select-list",
            method: "get",
            ref: "dma_searchReq",
            target: "dlt_listRes=body"
    };

    await $c.sbm.executeDynamic(sbmOptions);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dlt_listRes.removeAll();
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @param {*} v_Currow v_Currow
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function(v_Currow) {

    if (v_Currow === undefined) {
        v_Currow = dlt_listRes.getRowPosition();
    }
    const res = dlt_listRes.getRowJSON(v_Currow);
    $c.win.closePopup(res);
};
